const event = $json;

// Safe number handling (even if not string)
const phone =
  event["Organizer Phone number"]
    ? String(event["Organizer Phone number"])
    : "";

const fee =
  event["Registration fee(₹)"]
    ? Number(event["Registration fee(₹)"])
    : 0;

// Hashtag mapping
const eventHashtags = {
  Cultural: "#CollegeEvent #CulturalFest #CampusLife",
  Technical: "#TechEvent #Hackathon #Innovation",
  Sports: "#SportsMeet #CollegeSports #GameOn",
};

const hashtags =
  eventHashtags[event["Type of event"]] ||
  "#CollegeEvent";

// Instagram caption
return [
  {
    json: {
      caption: `
🎉 ${event["Event Name"]} 🎉

🏫 Club: ${event["Club name"]}
📅 Date: ${event["Date"]}
⏰ Time: ${event["Start Time"]} - ${event["End Time"]}
📍 Venue: ${event["Venue"]}

📝 ${event["Description"]}

📞 Contact: ${phone}
💰 Registration Fee: ₹${fee}

${hashtags}
`.trim(),
    },
  },
];

const items = $input.all();

return items.map(item => {
  const event = item.json;

  const phone = event["Organizer Phone number"]
    ? String(event["Organizer Phone number"])
    : "Not provided";

  const fee = event["Registration fee(₹)"]
    ? Number(event["Registration fee(₹)"])
    : 0;

  return {
    json: {
      message: `🎉 *${event["Event Name"]}* 🎉

🏫 Club: ${event["Club name"]}
📅 Date: ${event["Date"]}
⏰ Time: ${event["Start Time"]} - ${event["End Time"]}
📍 Venue: ${event["Venue"]}

📝 ${event["Description"]}

📞 Contact: ${phone}
💰 Registration Fee: ₹${fee}`
    }
  };
});

const items = $input.all();

function parseDate(dateStr) {
  if (!dateStr) return new Date(0);

  // DD/MM/YYYY
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    return new Date(`${year}-${month}-${day}`);
  }

  // YYYY-MM-DD
  return new Date(dateStr);
}

items.sort((a, b) => {
  return parseDate(a.json.Date) - parseDate(b.json.Date);
});

return items;

const grouped = {};

$input.all().forEach(e => {
  // grouping key (use exact sheet header)
  const type = e.json["Type of event"] || e.json.TypeOfEvent || e.json.type || "Uncategorized";

  if (!grouped[type]) grouped[type] = [];

  grouped[type].push({
    // Use exact headings as object keys (strings) so downstream nodes/Sheets see exact column names
    "Event id": e.json["Event id"] || e.json.eventId || e.json.event_id || "",
    "Club name": e.json["Club name"] || e.json.clubName || e.json.club_name || "",
    "Event Name": e.json["Event Name"] || e.json.eventName || e.json.Event_Name || "",
    "Type of event": e.json["Type of event"] || e.json.TypeOfEvent || e.json.type || "",
    "Date": e.json["Date"] || e.json.date || e.json.dateOfEvent || "",
    "Start Time": e.json["Start Time"] || e.json.startTime || e.json.timeOfEvent || "",
    "End Time": e.json["End Time"] || e.json.endTime || "",
    "Venue": e.json["Venue"] || e.json.venue || "",
    "Team members": e.json["Team members"] || e.json.teamMembers || e.json.team_members || "",
    "Registration fee(₹)": e.json["Registration fee(₹)"] || e.json.registrationFee || e.json.registration_fee || "",
    "Prize": e.json["Prize"] || e.json.prize || "",
    "Chief guest": e.json["Chief guest"] || e.json.chiefGuest || e.json.chief_guest || "",
    "Description": e.json["Description"] || e.json.description || "",
    "Images": e.json["Images"] || e.json.images || e.json.image || "",
    "Organizer Name": e.json["Organizer Name"] || e.json.organizerName || e.json.organizer_name || "",
    "Organizer Phone number": e.json["Organizer Phone number"] || e.json.organizerPhone || e.json.organizer_phone || ""
  });
});

return Object.entries(grouped).map(([typeOfEvent, events]) => ({
  json: {
    "Type of event": typeOfEvent,
    events
  }
}));

// ---------- helpers (no external modules) ----------

function parseDateParts(s) {
  if (!s) return null;
  s = String(s).trim();
  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);
  if (m) return { y: +m[1], m: +m[2], d: +m[3] };

  const parts = s.split(/[-\/]/).map(p => p.trim());
  if (parts.length === 3) {
    let [p1, p2, p3] = parts;
    if (/^\d{4}$/.test(p1)) return { y: +p1, m: +p2, d: +p3 };
    let d = p1, mth = p2, y = p3;
    if (y.length === 2) y = '20' + y;
    return { y: +y, m: +mth, d: +d };
  }

  const dt = new Date(s);
  if (!isNaN(dt)) return { y: dt.getFullYear(), m: dt.getMonth() + 1, d: dt.getDate() };

  return null;
}

function parseTimeParts(t) {
  if (!t) return { hh: 0, mm: 0, ss: 0 };
  t = String(t).trim();
  const m24 = t.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (m24) return { hh: +m24[1], mm: +m24[2], ss: +(m24[3] || 0) };

  const m12 = t.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)$/i);
  if (m12) {
    let hh = +m12[1], mm = +m12[2], ss = +(m12[3] || 0);
    const ampm = m12[4].toUpperCase();
    if (ampm === 'PM' && hh < 12) hh += 12;
    if (ampm === 'AM' && hh === 12) hh = 0;
    return { hh, mm, ss };
  }
  return { hh: 0, mm: 0, ss: 0 };
}

function buildLocalDate(dateStr, timeStr) {
  const p = parseDateParts(dateStr);
  if (!p) return null;
  const t = parseTimeParts(timeStr);
  return new Date(p.y, p.m - 1, p.d, t.hh || 0, t.mm || 0, t.ss || 0, 0);
}

// ---------- main ----------

const items = $items();
const now = new Date();
const ms = 24 * 60 * 60 * 1000;

const nextWeek = [];
const nextMonth = [];
const nextTwoMonths = [];

items.forEach(it => {
  // Read date/time from the sheet — primary exact headings used first
  const dateRaw = (
    it.json["Date"] ||
    it.json.Date ||
    it.json.date ||
    it.json.dateOfEvent ||
    ""
  ).toString().trim();

  // prefer "Start Time" for event start; fallback to timeOfEvent or time
  const startTimeRaw = (
    it.json["Start Time"] ||
    it.json["StartTime"] ||
    it.json.startTime ||
    it.json.timeOfEvent ||
    it.json.time ||
    ""
  ).toString().trim();

  // optional end time
  const endTimeRaw = (
    it.json["End Time"] ||
    it.json["EndTime"] ||
    it.json.endTime ||
    ""
  ).toString().trim();

  if (!dateRaw) return; // skip rows without a Date

  const eventDate = buildLocalDate(dateRaw, startTimeRaw);
  if (!eventDate || isNaN(eventDate)) return;

  const diffMs = eventDate.getTime() - now.getTime();
  const diffDays = Math.floor(diffMs / ms);

  // Build event object using the exact headings provided
  const eventObj = {
    "Event id": it.json["Event id"] || it.json.eventId || it.json.event_id || "",
    "Club name": it.json["Club name"] || it.json.clubName || it.json.Club_Name || "",
    "Event Name": it.json["Event Name"] || it.json.eventName || it.json.Event_Name || "",
    "Type of event": it.json["Type of event"] || it.json.TypeOfEvent || it.json.type || "",
    "Date": dateRaw,
    "Start Time": startTimeRaw,
    "End Time": endTimeRaw,
    "Venue": it.json["Venue"] || it.json.venue || "",
    "Team members": it.json["Team members"] || it.json.teamMembers || it.json.team_members || "",
    "Registration fee(₹)": it.json["Registration fee(₹)"] || it.json.registrationFee || it.json.registration_fee || "",
    "Prize": it.json["Prize"] || it.json.prize || "",
    "Chief guest": it.json["Chief guest"] || it.json.chiefGuest || it.json.chief_guest || "",
    "Description": it.json["Description"] || it.json.description || "",
    "Images": it.json["Images"] || it.json.images || it.json.image || "",
    "Organizer Name": it.json["Organizer Name"] || it.json.organizerName || it.json.organizer_name || "",
    "Organizer Phone number": it.json["Organizer Phone number"] || it.json.organizerPhone || it.json.organizer_phone || "",
    eventDateISO: eventDate.toISOString(),
    diffDays
  };

  if (diffDays >= 0 && diffDays <= 7) {
    nextWeek.push(eventObj);
  } else if (diffDays >= 8 && diffDays <= 30) {
    nextMonth.push(eventObj);
  } else if (diffDays >= 31 && diffDays <= 60) {
    nextTwoMonths.push(eventObj);
  }
});

// Sort each list by parsed date ascending (uses eventDateISO)
const sortByDate = arr => arr.sort((a, b) => new Date(a.eventDateISO) - new Date(b.eventDateISO));
sortByDate(nextWeek);
sortByDate(nextMonth);
sortByDate(nextTwoMonths);

// Return grouped arrays
return [
  {
    json: {
      nextWeek,
      nextMonth,
      nextTwoMonths
    }
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
// n8n Code node (JavaScript)
// Configure this node to have 4 outputs (or change the number of outputs below)
// Output mapping (example):
// 0 -> Create Google Calendar event node
// 1 -> Send SMS / Telegram node
// 2 -> Send Gmail node
// 3 -> Send Slack node

// Get all input items
const incoming = this.getInputData(); // n8n helper: array of { json: {...}, binary?: {...} }

const outCreateEvent = [];
const outText = [];
const outGmail = [];
const outSlack = [];

// helper to format a date/time nicely (fallback to original if parse fails)
function fmtDate(d) {
  if (!d) return '';
  try {
    const dt = new Date(d);
    if (Number.isNaN(dt.getTime())) return String(d);
    return dt.toLocaleString(); // uses host locale; change to dt.toISOString() if you need ISO
  } catch (e) {
    return String(d);
  }
}

for (const item of incoming) {
  const js = item.json || {};

  // Common fields we try to extract. Adjust keys to match your Google Calendar / Sheets keys.
  const title = js.summary || js.title || js.eventTitle || js.name || 'No title';
  const description = js.description || js.notes || '';
  const start = js.start?.dateTime || js.start || js.startTime || js.start_date || js.start_time;
  const end = js.end?.dateTime || js.end || js.endTime || js.end_date || js.end_time;
  const location = js.location || js.place || '';
  // possible contact fields (sheet may contain these)
  const toEmail = js.email || js.toEmail || js.userEmail || js.ownerEmail || undefined;
  const chatId = js.chatId || js.telegramChatId || js.phone || undefined;
  const slackChannel = js.slackChannel || js.channel || undefined;

  // Build a plain text message
  const messageTextParts = [
    `*${title}*`,
    start ? `When: ${fmtDate(start)}` : '',
    end ? `Until: ${fmtDate(end)}` : '',
    location ? `Where: ${location}` : '',
    description ? `Details: ${description}` : ''
  ].filter(Boolean);

  const messageText = messageTextParts.join('\n');

  // --- Output for Create Calendar Event node ---
  // Many calendar nodes expect a JSON with "summary", "start", "end", "description", "location", "attendees" etc.
  outCreateEvent.push({
    json: {
      summary: title,
      description,
      location,
      start: (start ? { dateTime: (new Date(start)).toISOString() } : undefined),
      end:   (end   ? { dateTime: (new Date(end)).toISOString() }   : undefined),
      // attendees: [{email: toEmail}] // uncomment if you want to pass attendees
    }
  });

  // --- Output for Text / Telegram / SMS node ---
  // Many messaging nodes expect { chatId, text } (or { to, message } for SMS providers).
  outText.push({
    json: {
      chatId,             // if your Telegram node expects chatId here
      phone: chatId,      // or if it's an SMS node expecting phone
      text: messageText,
      rawInput: js        // pass original data for debugging if needed
    }
  });

  // --- Output for Gmail node ---
  // Gmail node often expects: { to, subject, html/text }
  outGmail.push({
    json: {
      to: toEmail || '',   // if blank, Gmail "Send" node may use "me" depending on config
      subject: `Reminder: ${title}`,
      text: messageText,
      html: `<p>${messageText.replace(/\n/g, '<br/>')}</p>`
    }
  });

  // --- Output for Slack node ---
  // Slack node usually accepts channel and text (or blocks). Adjust to your node type.
  outSlack.push({
    json: {
      channel: slackChannel || '#general',
      text: messageText,
      attachments: [],     // optional: map more structured data into attachments/blocks
      original: js
    }
  });
}

// Return arrays in the exact order of node outputs
return [outCreateEvent, outText, outGmail, outSlack];
